mapper.select:
/* NewChangeMspReadMapper.selectDisPrmtId */ SELECT DISTINCT PRMT_ID FROM VW_DIS_PRMT_DTL A WHERE 1=1 AND TO_CHAR(SYSDATE,'YYYYMMDDHH24MISS') BETWEEN A.STRT_DTTM AND A.END_DTTM AND USG_YN = 'Y' AND ORGN_ID = #{agentCd} AND SLS_TP = #{slsTp}
AND INTM_YN = 'N'
AND INTM_YN = 'Y' AND MODEL_ID = (SELECT RPRS_PRDT_ID FROM CMN_INTM_MDL A WHERE PRDT_ID = #{modelId})
AND ENGG_SRL LIKE '%'||#{modelMonthly}||'%' AND RATE_CD = #{rateCd} AND EVNT_CD = 'NAC'

/* NewChangeMspReadMapper.selectPromoBaseAmt */
SELECT ROUND(SUM(BASE_AMT) * 1.1, 0)
FROM MSP_RATE_MST
WHERE RATE_CD IN (
  SELECT DISTINCT SOC
  FROM VW_DIS_PRMT_DTL
  WHERE PRMT_ID IN

    #{prmtId}

)
